files.content:
/* Enforce hidden attribute */
[hidden] {
  display: none !important;
}

:root {
  --color-bg: #222034;
  --color-panel: #45283c;
  --color-panel-border: #693130;
  --color-accent: #f4b41b;
  --color-accent-dark: #b86f18;
  --color-wood-top: #8f563b;
  --color-wood-body: #663931;
  --color-wood-shadow: #3b1d22;
  --color-text-main: #fbf5ef;
  --color-text-muted: #d9a066;
  --color-focus: #76428a;
  --pixel-border: 4px solid #140c1c;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  background-color: var(--color-bg);
  color: var(--color-text-main);
  font-family: "Courier New", Courier, monospace, monospace;
  font-size: 16px;
  min-height: 100vh;
  display: flex;
  justify-content: center;
  align-items: center;
  padding: 24px 16px;
}

.app-container {
  width: 100%;
  max-width: 840px;
  background-color: var(--color-panel);
  border: var(--pixel-border);
  box-shadow: 8px 8px 0px #140c1c;
  padding: 24px;
  display: flex;
  flex-direction: column;
  gap: 20px;
}

.shelf-header {
  text-align: center;
}

.pixel-title {
  font-size: 28px;
  font-weight: 800;
  letter-spacing: 2px;
  text-transform: uppercase;
  color: var(--color-accent);
  text-shadow: 3px 3px 0px #140c1c;
  margin-bottom: 6px;
}

.pixel-subtitle {
  color: var(--color-text-muted);
  font-size: 16px;
}

.controls-card {
  background: #321b2c;
  border: 3px solid #140c1c;
  padding: 16px;
  display: flex;
  flex-direction: column;
  gap: 16px;
  box-shadow: inset 3px 3px 0px rgba(0,0,0,0.4);
}

.control-group {
  display: flex;
  flex-direction: column;
  gap: 6px;
}

.control-group-inline {
  display: flex;
  flex-wrap: wrap;
  gap: 16px;
  align-items: flex-end;
}

.control-subgroup {
  flex: 1;
  min-width: 160px;
  display: flex;
  flex-direction: column;
  gap: 6px;
}

.btn-wrapper {
  min-width: 200px;
}

.control-label {
  font-size: 16px;
  font-weight: bold;
  color: var(--color-accent);
  text-transform: uppercase;
}

.pixel-input,
.pixel-select,
.pixel-btn {
  font-family: inherit;
  font-size: 16px;
  background-color: var(--color-text-main);
  color: #140c1c;
  border: 3px solid #140c1c;
  border-radius: 0;
  padding: 10px 12px;
  outline: none;
  box-shadow: 3px 3px 0px #140c1c;
  width: 100%;
}

.pixel-input:focus,
.pixel-select:focus,
.pixel-btn:focus {
  outline: 3px dashed var(--color-accent);
  background-color: #fff9e6;
}

.pixel-btn {
  cursor: pointer;
  background-color: var(--color-accent);
  font-weight: bold;
  text-transform: uppercase;
  display: flex;
  align-items: center;
  justify-content: center;
  transition: none;
}

.pixel-btn:hover {
  background-color: #ffd15c;
}

.pixel-btn:active {
  transform: translate(2px, 2px);
  box-shadow: 1px 1px 0px #140c1c;
}

.shelf-wrapper {
  margin-top: 8px;
  display: flex;
  flex-direction: column;
}

.shelf-board {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(160px, 1fr));
  gap: 16px;
  align-items: end;
  min-height: 220px;
  padding: 12px 12px 0 12px;
}

.shelf-plank {
  height: 20px;
  background-color: var(--color-wood-top);
  border: 3px solid #140c1c;
  border-top: 4px solid #ab7556;
  box-shadow: 0px 6px 0px var(--color-wood-shadow);
  margin-top: -3px;
}

.book-card {
  position: relative;
  border: 3px solid #140c1c;
  padding: 12px 10px;
  color: #140c1c;
  display: flex;
  flex-direction: column;
  justify-content: space-between;
  min-height: 190px;
  box-shadow: 4px 4px 0px rgba(0, 0, 0, 0.4);
  user-select: none;
  transition: none;
}

.book-card:hover {
  transform: translateY(-4px);
  box-shadow: 4px 8px 0px #140c1c;
}

.book-spine-line {
  position: absolute;
  top: 0;
  bottom: 0;
  left: 6px;
  width: 4px;
  background: rgba(0, 0, 0, 0.25);
}

.book-title {
  font-size: 16px;
  font-weight: bold;
  line-height: 1.25;
  margin-left: 8px;
  word-break: break-word;
}

.book-meta {
  margin-left: 8px;
  margin-top: 8px;
  display: flex;
  flex-direction: column;
  gap: 4px;
}

.book-author {
  font-size: 14px;
  font-weight: 600;
  opacity: 0.9;
}

.book-year {
  font-size: 13px;
  font-weight: bold;
  background-color: rgba(0, 0, 0, 0.15);
  display: inline-block;
  padding: 2px 4px;
  align-self: flex-start;
}

/* Palette styles for books */
.theme-emerald {
  background-color: #5b9b76;
  border-left-width: 6px;
}
.theme-crimson {
  background-color: #c75c5c;
  border-left-width: 6px;
}
.theme-amber {
  background-color: #e69c47;
  border-left-width: 6px;
}
.theme-azure {
  background-color: #4b80ca;
  border-left-width: 6px;
}
.theme-purple {
  background-color: #925fa3;
  border-left-width: 6px;
}
.theme-sand {
  background-color: #d1b87c;
  border-left-width: 6px;
}
.theme-teal {
  background-color: #438f99;
  border-left-width: 6px;
}
.theme-coral {
  background-color: #d47065;
  border-left-width: 6px;
}

.no-results-msg {
  text-align: center;
  padding: 40px 16px;
  color: var(--color-accent);
  font-size: 18px;
  font-weight: bold;
}

.shelf-footer {
  display: flex;
  justify-content: flex-end;
}

.pixel-counter {
  font-size: 14px;
  color: var(--color-text-muted);
}

@media (max-width: 500px) {
  .shelf-board {
    grid-template-columns: 1fr;
  }
  .control-group-inline {
    flex-direction: column;
    align-items: stretch;
  }
  .pixel-title {
    font-size: 22px;
  }
}

const BOOKS = [
  {
    id: 1,
    title: "Moby Dick",
    author: "Herman Melville",
    year: 1851,
    theme: "theme-azure"
  },
  {
    id: 2,
    title: "Pride and Prejudice",
    author: "Jane Austen",
    year: 1813,
    theme: "theme-coral"
  },
  {
    id: 3,
    title: "The Great Gatsby",
    author: "F. Scott Fitzgerald",
    year: 1925,
    theme: "theme-emerald"
  },
  {
    id: 4,
    title: "Frankenstein",
    author: "Mary Shelley",
    year: 1818,
    theme: "theme-purple"
  },
  {
    id: 5,
    title: "1984",
    author: "George Orwell",
    year: 1949,
    theme: "theme-amber"
  },
  {
    id: 6,
    title: "Jane Eyre",
    author: "Charlotte Brontë",
    year: 1847,
    theme: "theme-teal"
  },
  {
    id: 7,
    title: "The Hobbit",
    author: "J.R.R. Tolkien",
    year: 1937,
    theme: "theme-emerald"
  },
  {
    id: 8,
    title: "Dracula",
    author: "Bram Stoker",
    year: 1897,
    theme: "theme-crimson"
  }
];

const state = {
  searchQuery: "",
  sortBy: "title",
  ascending: true
};

const searchInput = document.getElementById("search-input");
const sortSelect = document.getElementById("sort-select");
const directionToggle = document.getElementById("direction-toggle");
const directionLabel = document.getElementById("direction-label");
const bookshelf = document.getElementById("bookshelf");
const noResultsMsg = document.getElementById("no-results");
const countIndicator = document.getElementById("count-indicator");

function getProcessedBooks() {
  const query = state.searchQuery.trim().toLowerCase();

  const filtered = BOOKS.filter(book => {
    if (!query) return true;
    return (
      book.title.toLowerCase().includes(query) ||
      book.author.toLowerCase().includes(query)
    );
  });

  filtered.sort((a, b) => {
    let comparison = 0;
    if (state.sortBy === "year") {
      comparison = a.year - b.year;
    } else if (state.sortBy === "author") {
      comparison = a.author.localeCompare(b.author);
    } else {
      comparison = a.title.localeCompare(b.title);
    }
    return state.ascending ? comparison : -comparison;
  });

  return filtered;
}

function render() {
  const books = getProcessedBooks();
  bookshelf.innerHTML = "";

  if (books.length === 0) {
    noResultsMsg.hidden = false;
  } else {
    noResultsMsg.hidden = true;
    books.forEach(book => {
      const card = document.createElement("article");
      card.className = `book-card ${book.theme}`;
      card.setAttribute("tabindex", "0");
      card.setAttribute("aria-label", `${book.title} by ${book.author}, published in ${book.year}`);

      const spineLine = document.createElement("div");
      spineLine.className = "book-spine-line";
      spineLine.setAttribute("aria-hidden", "true");

      const title = document.createElement("h2");
      title.className = "book-title";
      title.textContent = book.title;

      const meta = document.createElement("div");
      meta.className = "book-meta";

      const author = document.createElement("span");
      author.className = "book-author";
      author.textContent = book.author;

      const year = document.createElement("span");
      year.className = "book-year";
      year.textContent = book.year;

      meta.appendChild(author);
      meta.appendChild(year);

      card.appendChild(spineLine);
      card.appendChild(title);
      card.appendChild(meta);

      bookshelf.appendChild(card);
    });
  }

  countIndicator.textContent = `Showing ${books.length} of ${BOOKS.length} books`;
}

searchInput.addEventListener("input", (e) => {
  state.searchQuery = e.target.value;
  render();
});

sortSelect.addEventListener("change", (e) => {
  state.sortBy = e.target.value;
  render();
});

directionToggle.addEventListener("click", () => {
  state.ascending = !state.ascending;
  directionToggle.setAttribute("aria-pressed", (!state.ascending).toString());
  const orderType = state.sortBy === "year" ? "Old-New" : "A–Z";
  const reverseType = state.sortBy === "year" ? "New-Old" : "Z–A";
  directionLabel.textContent = state.ascending
    ? `Ascending (${orderType})`
    : `Descending (${reverseType})`;
  render();
});

// Initial render
render();
